root_selector:
(
  $text := function($value) {
    $type($value) = "string" ? ($value != "" ? $value : "N/A") : "N/A"
  };
  $passport := function($url, $kind) {
    $type($url) = "string" ?
      ($contains($url, /^https:\/\/github\.com\/SatoryKono\/BioactivityDataAcquisition\/blob\/main\/docs\/04-reference\/passports\/(workflows|pipelines)\/[A-Za-z0-9%._-]+\.md$/)
        and $contains($url, "/passports/" & $kind & "/") ?
          $substringAfter($url, "https://github.com/SatoryKono/BioactivityDataAcquisition/") : "") : ""
  };
  index_state = "valid_empty" and $exists(items) and $count(items) = 0 ?
    [{
      "pipeline": "VALID EMPTY", "pipeline_label": "VALID EMPTY",
      "workflow_id": "N/A", "provider": "N/A", "run_id": "", "run_label": "—",
      "run_type": "", "workflow_scope": "", "started_at": null,
      "duration_display": "N/A", "status": "N/A", "saved_evidence_status": "N/A",
      "data_quality_status": "N/A", "replay_readiness_status": "N/A",
      "report_label": "", "report_url": "", "workflow_passport_url": "",
      "workflow_passport_path": "", "pipeline_passport_url": "", "pipeline_passport_path": ""
    }] :
    items.(
      $provider := $type(provider) = "string" ? provider : "";
      $pipelineValue := $text(pipeline);
      $run := $type(run_id) = "string" ? run_id : "";
      $prefix := $provider & "_";
      $pipelinePath := $passport(pipeline_passport_url, "pipelines");
      $merge([$, {
        "workflow_id": $text(workflow_id),
        "run_label": $run != "" ? ($length($run) > 8 ? $substring($run, 0, 8) & "…" : $run) : "N/A",
        "pipeline_label": $provider != "" ?
          ($substring($pipelineValue, 0, $length($prefix)) = $prefix ?
            $substring($pipelineValue, $length($prefix)) : $pipelineValue) : $pipelineValue,
        "workflow_passport_path": $passport(workflow_passport_url, "workflows"),
        "pipeline_passport_path": $pipelinePath,
        "pipeline_passport_url": $pipelinePath != "" ?
          "https://github.com/SatoryKono/BioactivityDataAcquisition/" & $pipelinePath : ""
      }])
    )
)
